from tinycsv import round_half_even
diffs=[]
for v in [2.675, 1.005, 8.835, 0.615, 2.665, 1.115, 3.145]:
    mine, builtin = round_half_even(v,2), round(v,2)
    if mine != builtin: diffs.append((v,mine,builtin))
print('cases where tinycsv differs from built-in round():')
for v,m,b in diffs: print(f'  {v}  tinycsv={m}  builtin={b}')
print(f'\n{len(diffs)} differences found -> the function is NOT redundant' if diffs else 'no differences -> redundant wrapper')
